<template>
  <div
    class="video-carousel"
    @click="onUserInteract"
  >
    <!-- Video Player — all videos rendered, only active one visible -->
    <div class="carousel-viewport">
      <!-- Shimmer shown while manifest loads or first video buffers -->
      <div v-if="loading || (videos.length > 0 && !videoLoaded)" class="video-shimmer">
        <img
          v-if="videos.length > 0 && activeVideo.posterUrl"
          :src="activeVideo.posterUrl"
          class="shimmer-poster"
          alt=""
        />
        <div v-else class="shimmer-pulse" />
      </div>

      <video
        v-for="(video, index) in videos"
        :key="video.id"
        :ref="'video-' + index"
        :src="getVideoSrc(index)"
        :poster="video.posterUrl || undefined"
        loop
        muted
        playsinline
        preload="metadata"
        class="carousel-video"
        :class="{ 'video-active': index === activeIndex }"
        @canplay="onVideoReady(index)"
      />
    </div>

    <!-- Bottom section: hint text + dots (reserve space even when loading) -->
    <div class="carousel-controls">
      <p class="carousel-hint" aria-live="polite">
        <template v-if="videos.length > 0">
          <Icon icon="mdi:lightbulb-outline" class="size-4 text-primary mr-1.5 inline-block align-middle" />
          <span class="align-middle">{{ translatedHint }}</span>
        </template>
        <span v-else>&nbsp;</span>
      </p>

      <div class="carousel-dots">
        <button
          v-for="(video, index) in videos"
          :key="video.id"
          class="carousel-dot"
          :class="{ 'dot-active': index === activeIndex }"
          :aria-label="translatedTitle(video)"
          @click="goToSlide(index)"
        >
          <svg v-if="index === activeIndex" class="dot-progress" viewBox="0 0 20 20">
            <circle cx="10" cy="10" r="8" class="dot-progress-track" />
            <circle
              cx="10" cy="10" r="8"
              class="dot-progress-fill"
              :style="{ strokeDasharray: progressCircumference, strokeDashoffset: progressOffset }"
            />
          </svg>
        </button>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import logger from 'src/utils/logger';
import { tol } from 'src/boot/tolgee';

export interface VideoManifestEntry {
  id: string;
  title: string;
  subtitle: string;
  hintText: string;
  hintKey?: string;
  titleKey?: string;
  videoUrl: string;
  posterUrl?: string;
  developer: { name: string; avatarUrl: string };
  keyboardShortcut?: string[];
  order: number;
  enabled: boolean;
}

export interface VideoManifest {
  version: number;
  updatedAt: string;
  videos: VideoManifestEntry[];
}

/** Derives a Tolgee translation key from a video id and field name. */
function toTolgeeKey(videoId: string, field: string): string {
  return `video_carousel_${videoId.replace(/-/g, '_')}_${field}`;
}

const CDN_MANIFEST_URL = 'https://docbits-videos.fra1.cdn.digitaloceanspaces.com/manifest.json';
const AUTO_ADVANCE_MS = 7_300;
const MAX_VIDEOS = 6;
const PROGRESS_CIRCUMFERENCE = 2 * Math.PI * 8; // r=8

export default defineComponent({
  name: 'VideoCarousel',

  emits: ['user-interact'],

  data() {
    return {
      videos: [] as VideoManifestEntry[],
      manifestVersion: '',
      activeIndex: 0,
      loading: true,
      videoLoaded: false,
      loadedVideos: new Set<number>(),
      autoAdvanceTimer: null as ReturnType<typeof setInterval> | null,
      progressTimer: null as ReturnType<typeof setInterval> | null,
      progressValue: 0,
    };
  },

  computed: {
    activeVideo(): VideoManifestEntry {
      return this.videos[this.activeIndex] ?? {
        id: '',
        title: '',
        subtitle: '',
        hintText: '',
        videoUrl: '',
        developer: { name: '', avatarUrl: '' },
        order: 0,
        enabled: true,
      };
    },

    translatedHint(): string {
      const video = this.activeVideo;
      if (!video.id) return '';
      const key = video.hintKey || toTolgeeKey(video.id, 'hint');
      return tol.t({ key, defaultValue: video.hintText });
    },

    progressCircumference(): number {
      return PROGRESS_CIRCUMFERENCE;
    },

    progressOffset(): number {
      const progress = this.progressValue / AUTO_ADVANCE_MS;
      return PROGRESS_CIRCUMFERENCE * (1 - progress);
    },
  },

  async mounted() {
    await this.fetchManifest();
    if (this.videos.length === 0) return;
    await this.$nextTick();
    const firstEl = this.getVideoEl(0);
    if (firstEl) {
      firstEl.preload = 'auto';
      firstEl.load();
    }
    this.playVideo(this.activeIndex);
    this.startAutoAdvance();
  },

  beforeUnmount() {
    this.stopAutoAdvance();
  },

  watch: {
    activeIndex(newIndex: number, oldIndex: number) {
      this.pauseVideo(oldIndex);
      this.playVideo(newIndex);
    },
  },

  methods: {
    async fetchManifest() {
      try {
        const response = await fetch(CDN_MANIFEST_URL);
        if (!response.ok) {
          throw new Error(`Manifest fetch failed: ${response.status}`);
        }
        const manifest: VideoManifest = await response.json();
        this.manifestVersion = manifest.updatedAt || String(Date.now());
        const enabled = manifest.videos.filter((v) => v.enabled);
        this.videos = this.pickRandom(enabled, MAX_VIDEOS);
        logger.info(`[VideoCarousel] Selected ${this.videos.length} of ${enabled.length} videos`);
      } catch (err) {
        logger.error('[VideoCarousel] Failed to fetch manifest:', err);
      } finally {
        this.loading = false;
      }
    },

    getVideoSrc(index: number): string {
      if (index < 0 || index >= this.videos.length) return '';
      return `${this.videos[index].videoUrl}?v=${this.manifestVersion}`;
    },

    getVideoEl(index: number): HTMLVideoElement | null {
      const refs = this.$refs['video-' + index] as HTMLVideoElement[] | HTMLVideoElement | undefined;
      if (!refs) return null;
      return Array.isArray(refs) ? refs[0] : refs;
    },

    playVideo(index: number) {
      const el = this.getVideoEl(index);
      if (!el) return;

      if (this.loadedVideos.has(index)) {
        // Already loaded — play immediately
        el.currentTime = 0;
        el.play().catch(() => {});
        this.videoLoaded = true;
      } else {
        // Not yet loaded — trigger full load and play when ready
        el.preload = 'auto';
        el.load();
        const onReady = () => {
          el.removeEventListener('canplay', onReady);
          el.currentTime = 0;
          el.play().catch(() => {});
          this.videoLoaded = true;
        };
        el.addEventListener('canplay', onReady);
      }
    },

    pauseVideo(index: number) {
      const el = this.getVideoEl(index);
      if (el) el.pause();
    },

    preloadAllRemaining() {
      // Videos are small (0.5-0.7MB), load them all after first plays
      this.videos.forEach((_video, index) => {
        if (index === this.activeIndex) return;
        const el = this.getVideoEl(index);
        if (el && el.preload !== 'auto') {
          el.preload = 'auto';
          el.load();
        }
      });
    },

    startAutoAdvance() {
      this.stopAutoAdvance();
      this.progressValue = 0;

      this.progressTimer = setInterval(() => {
        this.progressValue += 50;
      }, 50);

      this.autoAdvanceTimer = setInterval(() => {
        this.nextSlide();
      }, AUTO_ADVANCE_MS);
    },

    stopAutoAdvance() {
      if (this.autoAdvanceTimer) {
        clearInterval(this.autoAdvanceTimer);
        this.autoAdvanceTimer = null;
      }
      if (this.progressTimer) {
        clearInterval(this.progressTimer);
        this.progressTimer = null;
      }
    },

    nextSlide() {
      if (this.videos.length === 0) return;
      this.progressValue = 0;
      this.activeIndex = (this.activeIndex + 1) % this.videos.length;
    },

    goToSlide(index: number) {
      if (index === this.activeIndex) return;
      this.activeIndex = index;
      this.startAutoAdvance();
    },

    onVideoReady(index: number) {
      this.loadedVideos.add(index);
      if (index === this.activeIndex) {
        this.videoLoaded = true;
      }
      // Once the first video is playable, start loading all others
      if (this.loadedVideos.size === 1) {
        this.preloadAllRemaining();
      }
    },

    pickRandom(videos: VideoManifestEntry[], count: number): VideoManifestEntry[] {
      if (videos.length <= count) return [...videos].sort((a, b) => a.order - b.order);
      // Fisher-Yates shuffle, then take first `count`
      const shuffled = [...videos];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }
      return shuffled.slice(0, count).sort((a, b) => a.order - b.order);
    },

    translatedTitle(video: VideoManifestEntry): string {
      const key = video.titleKey || toTolgeeKey(video.id, 'title');
      return tol.t({ key, defaultValue: video.title });
    },

    onUserInteract() {
      this.$emit('user-interact');
    },
  },
});
</script>

